// Extraction d'intention simple via regex (sans LLM)
const input = $input.first().json;
const message = (input.body?.message || input.message || '').toLowerCase();

// Patterns pour les traites
const traitePatterns = {
  'sukkah': 'Sukkah', 'souccah': 'Sukkah', 'sukka': 'Sukkah', 'soucca': 'Sukkah',
  'berakhot': 'Berakhot', 'berachot': 'Berakhot', 'brachot': 'Berakhot', 'brakhot': 'Berakhot',
  'pesachim': 'Pesachim', 'pessahim': 'Pesachim', 'pessachim': 'Pesachim',
  'shabbat': 'Shabbat', 'shabat': 'Shabbat', 'chabbat': 'Shabbat',
  'eruvin': 'Eruvin', 'erouvin': 'Eruvin', 'eiruvin': 'Eruvin',
  'bekhorot': 'Bekhorot', 'bechorot': 'Bekhorot'
};

// Patterns pour les commentateurs
const commentatorPatterns = {
  'rashi': 'Rashi', 'rachi': 'Rashi',
  'tosafot': 'Tosafot', 'tossafot': 'Tosafot', 'tosfot': 'Tosafot',
  'steinsaltz': 'Steinsaltz', 'steinzaltz': 'Steinsaltz',
  'ritva': 'Ritva',
  'meiri': 'Meiri',
  'rashash': 'Rashash',
  'rosh': 'Rosh',
  'maharam': 'Maharam',
  'all': 'all', 'tous': 'all', 'tout': 'all'
};

let intent = { traite: null, page: null, commentator: 'all', action: 'get_commentary' };
let error = null;

// Chercher le traite
for (const [pattern, name] of Object.entries(traitePatterns)) {
  if (message.includes(pattern)) {
    intent.traite = name;
    break;
  }
}

// Chercher la page (format: 10a, 28b, 2a, etc.)
const pageMatch = message.match(/\b(\d{1,3}[ab])\b/);
if (pageMatch) {
  intent.page = pageMatch[1];
}

// Chercher le commentateur
for (const [pattern, name] of Object.entries(commentatorPatterns)) {
  if (message.includes(pattern)) {
    intent.commentator = name;
    break;
  }
}

// Validation
if (!intent.traite) {
  error = 'Traite non reconnu. Traites disponibles: Sukkah, Berakhot, Pesachim, Shabbat, Eruvin, Bekhorot';
} else if (!intent.page) {
  error = 'Page non reconnue. Format attendu: 10a, 28b, 2a, etc.';
}

return [{ json: { intent, error, originalMessage: message } }];

// Formater les commentaires pour Discord
const input = $input.first().json;
const intent = $('Extract Intent (Regex)').first().json.intent;

let commentaries = input.commentaries || [];
const sourceText = input.source_text || input;

// Filtrer par commentateur si specifie
if (intent.commentator && intent.commentator.toLowerCase() !== 'all') {
  const targetCommentator = intent.commentator.toLowerCase();
  commentaries = commentaries.filter(c => {
    const name = (c.commentator || '').toLowerCase();
    return name.includes(targetCommentator) || targetCommentator.includes(name);
  });
}

// Limiter le nombre de commentaires
const maxComments = 5;
const displayedComments = commentaries.slice(0, maxComments);

// Construire le titre
let title = `${intent.traite} ${intent.page}`;
if (intent.commentator && intent.commentator.toLowerCase() !== 'all') {
  title += ` - ${intent.commentator}`;
}

// Description
let description = '';
if (displayedComments.length === 0) {
  description = 'Aucun commentaire trouve pour cette recherche.';
} else {
  description = `${commentaries.length} commentaire(s) trouve(s)`;
  if (commentaries.length > maxComments) {
    description += ` (affichage des ${maxComments} premiers)`;
  }
}

// Creer les fields pour les commentaires
const fields = displayedComments.map((c, i) => {
  let text = c.text || c.hebrew_text || '';
  // Limiter la taille du texte pour Discord
  if (text.length > 300) {
    text = text.substring(0, 300) + '...';
  }
  return {
    name: `${c.commentator || 'Commentaire'} (seg. ${c.segment || i+1})`,
    value: text || '(texte non disponible)',
    inline: false
  };
});

// Ajouter la reference
if (sourceText && sourceText.reference) {
  fields.unshift({
    name: 'Reference',
    value: sourceText.reference,
    inline: true
  });
}

const embed = {
  title: title,
  description: description,
  color: 10181046,
  fields: fields.slice(0, 10),
  footer: { text: 'Torah Commentary Bot' },
  timestamp: new Date().toISOString()
};

return [{ json: { embed, stats: { total: commentaries.length, displayed: displayedComments.length } } }];

